input.content:
$ErrorActionPreference = "Stop"
$markerStart = "/* === kilo-claude-md-start === */"
$markerEnd = "/* === kilo-claude-md-end === */"
$cssPath = Join-Path $PSScriptRoot "kilo-claude-markdown.css"
$extRoot = Join-Path $env:USERPROFILE ".vscode\extensions"
$patch = Get-Content -LiteralPath $cssPath -Raw

$targets = Get-ChildItem -LiteralPath $extRoot -Directory -Filter "kilocode.kilo-code-*" |
  ForEach-Object {
    @(
      (Join-Path $_.FullName "dist\webview.css"),
      (Join-Path $_.FullName "dist\agent-manager.css")
    )
  } |
  Where-Object { Test-Path -LiteralPath $_ }

if (-not $targets) {
  Write-Error "No Kilo Code CSS files found under $extRoot"
}

foreach ($file in $targets) {
  $text = Get-Content -LiteralPath $file -Raw
  $start = $text.IndexOf($markerStart)
  $end = $text.IndexOf($markerEnd)
  if ($start -ge 0 -and $end -gt $start) {
    $end = $end + $markerEnd.Length
    $text = $text.Substring(0, $start).TrimEnd() + "`n" + $patch.TrimEnd() + "`n"
  } else {
    $text = $text.TrimEnd() + "`n" + $patch.TrimEnd() + "`n"
  }
  Set-Content -LiteralPath $file -Value $text -NoNewline -Encoding utf8
  Write-Output "Patched $file"
}

