input.content:
import struct
import sys
from pathlib import Path

PNG_MAGIC = b"\x89PNG\r\n\x1a\n"
MIN_BYTES = 8 * 1024
MIN_DIM = 100


def fail(message: str) -> None:
    print(f"FAIL {message}")
    raise SystemExit(1)


def main() -> None:
    if len(sys.argv) != 2:
        fail("usage: validate_png.py <png-path>")

    path = Path(sys.argv[1])
    if not path.is_file():
        fail(f"P1 missing file: {path}")

    data = path.read_bytes()
    if not data.startswith(PNG_MAGIC):
        fail("P2 not a PNG")

    if len(data) <= MIN_BYTES:
        fail(f"P3 file too small: {len(data)} bytes")

    if data[12:16] != b"IHDR":
        fail("P4 missing IHDR")

    width, height = struct.unpack(">II", data[16:24])
    if width < MIN_DIM or height < MIN_DIM:
        fail(f"P4 dimensions too small: {width}x{height}")

    print(f"PASS {path} {width}x{height} {len(data)} bytes")


if __name__ == "__main__":
    main()

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
$script = Join-Path $root "scripts\screenshot.ps1"
$validator = Join-Path $PSScriptRoot "validate_png.py"

Write-Output "P5 expected path contains Temp\kilo\vision\latest.png"

$path = & powershell -NoProfile -ExecutionPolicy Bypass -File $script -Target vscode
if (-not $path) {
  throw "P1 script printed no path"
}
$path = $path.Trim()
Write-Output "captured $path"

if ($path -notmatch "Temp\\kilo\\vision\\latest\.png$") {
  throw "P5 unexpected output path $path"
}

python $validator $path
if ($LASTEXITCODE -ne 0) {
  throw "validator failed"
}

Write-Output "ALL PROPERTIES PASSED"

