display.text:
param(
  [ValidateSet("vscode", "screen")]
  [string]$Target = "vscode",
  [string]$OutDir = (Join-Path $env:LOCALAPPDATA "Temp\kilo\vision")
)

$ErrorActionPreference = "Stop"

New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$outPath = Join-Path $OutDir "latest.png"

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

if (-not ("KiloWin32" -as [type])) {
  Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class KiloWin32 {
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
  [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
}
"@
}

function Get-PrimaryBounds {
  $bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
  return @{
    X = [int]$bounds.X
    Y = [int]$bounds.Y
    W = [int]$bounds.Width
    H = [int]$bounds.Height
  }
}

function Get-VsCodeBounds {
  $candidates = @(Get-Process -Name "Code" -ErrorAction SilentlyContinue |
    Where-Object { $_.MainWindowHandle -ne [IntPtr]::Zero -and [KiloWin32]::IsWindowVisible($_.MainWindowHandle) })

  $handle = $null
  foreach ($proc in $candidates) {
    if (-not [KiloWin32]::IsIconic($proc.MainWindowHandle)) {
      $handle = $proc.MainWindowHandle
      break
    }
  }
  if (-not $handle -and $candidates.Count -gt 0) {
    $handle = $candidates[0].MainWindowHandle
  }
  if (-not $handle) {
    return $null
  }

  $rect = New-Object KiloWin32+RECT
  $ok = [KiloWin32]::GetWindowRect($handle, [ref]$rect)
  if (-not $ok) {
    return $null
  }

  $width = [int]($rect.Right - $rect.Left)
  $height = [int]($rect.Bottom - $rect.Top)
  if ($width -lt 100 -or $height -lt 100) {
    return $null
  }

  return @{
    X = [int]$rect.Left
    Y = [int]$rect.Top
    W = $width
    H = $height
  }
}

$box = $null
if ($Target -eq "vscode") {
  $box = Get-VsCodeBounds
}
if (-not $box) {
  $box = Get-PrimaryBounds
}

$bitmap = New-Object System.Drawing.Bitmap $box.W, $box.H
$graphics = [System.Drawing.Graphics]::FromImage($bitmap)
try {
  $graphics.CopyFromScreen(
    $box.X,
    $box.Y,
    0,
    0,
    (New-Object System.Drawing.Size $box.W, $box.H)
  )
  $bitmap.Save($outPath, [System.Drawing.Imaging.ImageFormat]::Png)
} finally {
  $graphics.Dispose()
  $bitmap.Dispose()
}

if (-not (Test-Path -LiteralPath $outPath)) {
  throw "Screenshot was not written to $outPath"
}

Write-Output $outPath

input.content:
param(
  [ValidateSet("all", "screen", "vscode", "window")]
  [string]$Target = "all",
  [string]$Window = "",
  [switch]$List,
  [string]$OutDir = (Join-Path $env:LOCALAPPDATA "Temp\kilo\vision")
)

$ErrorActionPreference = "Stop"

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

if (-not ("KiloWin32" -as [type])) {
  Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class KiloWin32 {
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
  [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
}
"@
}

function Get-OpenWindows {
  Get-Process |
    Where-Object {
      $_.MainWindowHandle -ne [IntPtr]::Zero -and
      $_.MainWindowTitle -and
      [KiloWin32]::IsWindowVisible($_.MainWindowHandle)
    } |
    Sort-Object MainWindowTitle -Unique |
    ForEach-Object {
      [pscustomobject]@{
        Title = $_.MainWindowTitle
        Process = $_.ProcessName
        Handle = $_.MainWindowHandle
      }
    }
}

function Get-BoundsFromHandle {
  param($Handle)
  if (-not $Handle -or $Handle -eq [IntPtr]::Zero) {
    return $null
  }
  $rect = New-Object KiloWin32+RECT
  if (-not [KiloWin32]::GetWindowRect($Handle, [ref]$rect)) {
    return $null
  }
  $width = [int]($rect.Right - $rect.Left)
  $height = [int]($rect.Bottom - $rect.Top)
  if ($width -lt 50 -or $height -lt 50) {
    return $null
  }
  return @{
    X = [int]$rect.Left
    Y = [int]$rect.Top
    W = $width
    H = $height
  }
}

function Get-VirtualBounds {
  $bounds = [System.Windows.Forms.SystemInformation]::VirtualScreen
  return @{
    X = [int]$bounds.X
    Y = [int]$bounds.Y
    W = [int]$bounds.Width
    H = [int]$bounds.Height
  }
}

function Get-PrimaryBounds {
  $bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
  return @{
    X = [int]$bounds.X
    Y = [int]$bounds.Y
    W = [int]$bounds.Width
    H = [int]$bounds.Height
  }
}

function Get-WindowBoundsByName {
  param([string]$Name, [string]$ProcessName)
  $windows = @(Get-OpenWindows)
  $match = $windows
  if ($ProcessName) {
    $match = @($match | Where-Object { $_.Process -eq $ProcessName })
  }
  if ($Name) {
    $match = @($match | Where-Object { $_.Title -like "*$Name*" })
  }
  $visible = @($match | Where-Object { -not [KiloWin32]::IsIconic($_.Handle) })
  if ($visible.Count -gt 0) {
    return Get-BoundsFromHandle $visible[0].Handle
  }
  if ($match.Count -gt 0) {
    return Get-BoundsFromHandle $match[0].Handle
  }
  return $null
}

if ($List) {
  Get-OpenWindows | ForEach-Object { "{0}`t{1}" -f $_.Process, $_.Title }
  return
}

New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$outPath = Join-Path $OutDir "latest.png"

$box = $null
switch ($Target) {
  "all" { $box = Get-VirtualBounds }
  "screen" { $box = Get-PrimaryBounds }
  "vscode" { $box = Get-WindowBoundsByName -Name "" -ProcessName "Code" }
  "window" {
    if (-not $Window) {
      throw " -Target window requires -Window `"title substring`""
    }
    $box = Get-WindowBoundsByName -Name $Window
  }
}

if (-not $box) {
  $box = Get-VirtualBounds
}

$bitmap = New-Object System.Drawing.Bitmap $box.W, $box.H
$graphics = [System.Drawing.Graphics]::FromImage($bitmap)
try {
  $graphics.CopyFromScreen(
    $box.X,
    $box.Y,
    0,
    0,
    (New-Object System.Drawing.Size $box.W, $box.H)
  )
  $bitmap.Save($outPath, [System.Drawing.Imaging.ImageFormat]::Png)
} finally {
  $graphics.Dispose()
  $bitmap.Dispose()
}

if (-not (Test-Path -LiteralPath $outPath)) {
  throw "Screenshot was not written to $outPath"
}

Write-Output $outPath

