import hashlib
import re
import struct
import subprocess
import sys
from pathlib import Path

HOME = Path.home()
CSS = HOME / ".config" / "kilo" / "kilo-claude-markdown.css"
AGENTS = HOME / ".config" / "kilo" / "AGENTS.md"
VERIFY = HOME / ".kilo" / "skills" / "screen-vision" / "scripts" / "verify-css.ps1"
SHOT = HOME / ".kilo" / "skills" / "screen-vision" / "scripts" / "screenshot.ps1"
PATCH = HOME / ".config" / "kilo" / "patch-kilo-chat-css.ps1"
DIST_CSS = HOME / ".vscode" / "extensions"
PNG_MAGIC = b"\x89PNG\r\n\x1a\n"
fails = 0


def fail(prop: str, message: str) -> None:
    global fails
    fails += 1
    print(f"FAIL {prop} {message}")


def ok(prop: str, message: str = "") -> None:
    extra = f" {message}" if message else ""
    print(f"PASS {prop}{extra}")


def css_text() -> str:
    return CSS.read_text(encoding="utf-8")


def latest_kilo_dist() -> Path:
    dirs = sorted(
        DIST_CSS.glob("kilocode.kilo-code-*"),
        key=lambda p: p.stat().st_mtime,
        reverse=True,
    )
    if not dirs:
        raise FileNotFoundError("no Kilo extension")
    return dirs[0] / "dist"


def round1_css() -> None:
    print("=== ROUND 1 static CSS + writing ===")
    text = css_text()
    if re.search(r'\[data-component="markdown"\]\s*\{[^}]*font-size:\s*16px', text):
        ok("R1", "16px body")
    else:
        fail("R1", "missing font-size: 16px on markdown")

    if re.search(r'\[data-component="markdown"\]\s*\{[^}]*line-height:\s*1\.5\b', text):
        ok("R2", "line-height 1.5")
    else:
        fail("R2", "markdown line-height is not 1.5")

    for needle, label in (("h1 { font-size: 22px; }", "R3a"), ("h2 { font-size: 18px; }", "R3b"), ("h3 { font-size: 16px; }", "R3c")):
        if needle in text:
            ok(label, needle)
        else:
            fail(label, f"missing {needle}")

    if "white-space: pre-wrap" in text:
        ok("R4")
    else:
        fail("R4", "no pre-wrap")

    m = re.search(r'\[data-component="markdown"\] p \{[^}]*margin-bottom:\s*([0-9.]+)em', text)
    if m and float(m.group(1)) <= 0.5:
        ok("R5", m.group(1) + "em")
    else:
        fail("R5", str(m.group(1) if m else "missing"))

    m = re.search(r'\[data-component="markdown"\] > \* \+ \* \{[^}]*margin-top:\s*([0-9.]+)em', text)
    if m and float(m.group(1)) <= 0.65:
        ok("R6", m.group(1) + "em")
    else:
        fail("R6", str(m.group(1) if m else "missing"))

    agents = AGENTS.read_text(encoding="utf-8")
    if "Never crush user-facing answers into 1–4 dense lines" in agents or "never crush" in agents.lower():
        ok("R10")
    else:
        fail("R10", "AGENTS.md missing crush override")

    if "Talk to the user" in agents and "Change code" in agents:
        ok("R11")
    else:
        fail("R11", "missing two-mode split")

    if "Documents and PRs" in agents:
        ok("R12")
    else:
        fail("R12", "missing Documents and PRs")

    verify = VERIFY.read_text(encoding="utf-8")
    if "WaitSeconds -lt 12" in verify:
        ok("R9")
    else:
        fail("R9", "verify-css does not clamp wait to 12s")


def round2_patch() -> None:
    print("=== ROUND 2 patch + dist match + hot marker ===")
    proc = subprocess.run(
        ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", str(PATCH)],
        check=False,
        capture_output=True,
        text=True,
    )
    if proc.returncode != 0:
        fail("R7", proc.stderr[-400:] or proc.stdout[-400:])
        return
    dist = latest_kilo_dist()
    src = CSS.read_bytes()
    copied = (dist / "kilo-user-markdown.css").read_bytes()
    if hashlib.sha256(src).hexdigest() == hashlib.sha256(copied).hexdigest():
        ok("R7", "source == dist override")
    else:
        fail("R7", "dist override differs from source")

    js = (dist / "webview.js").read_bytes()[-8192:]
    if b"kilo-claude-hot-start" in js:
        ok("R8")
    else:
        fail("R8", "hot-reload marker missing from webview.js tail")


def png_info(path: Path) -> tuple[int, int, int]:
    data = path.read_bytes()
    if not data.startswith(PNG_MAGIC) or data[12:16] != b"IHDR":
        raise ValueError("not png")
    width, height = struct.unpack(">II", data[16:24])
    return width, height, len(data)


def round3_shot() -> None:
    print("=== ROUND 3 screenshot (no extra CSS wait; last patch already applied) ===")
    proc = subprocess.run(
        [
            "powershell",
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            str(SHOT),
            "-Target",
            "vscode",
        ],
        check=False,
        capture_output=True,
        text=True,
    )
    if proc.returncode != 0:
        fail("R13", proc.stderr[-400:] or proc.stdout[-400:])
        return
    path = Path(proc.stdout.strip().splitlines()[-1].strip())
    if not path.is_file():
        fail("R13", f"missing {path}")
        return
    width, height, nbytes = png_info(path)
    if nbytes > 8 * 1024 and width >= 100 and height >= 100:
        ok("R13", f"{path} {width}x{height} {nbytes}B")
    else:
        fail("R13", f"{width}x{height} {nbytes}B")
    if width >= 1200:
        ok("R14", f"width {width}")
    else:
        fail("R14", f"width {width} < 1200 (likely cropped)")


def main() -> None:
    round1_css()
    round2_patch()
    round3_shot()
    print("---")
    if fails:
        print(f"{fails} FAILED")
        raise SystemExit(1)
    print("ALL ROUNDS PASSED")


if __name__ == "__main__":
    main()

